solution.solution.rs:
fn report(names: Vec<String>) -> (String, Vec<String>) {
    if names.is_empty() {
        return ("no names".to_string(), names);
    }
    let text = format!("{} names: {}", names.len(), names.join(", "));
    (text, names)
}

fn longest(a: String, b: String) -> String {
    if b.len() > a.len() { b } else { a }
}

fn shout(text: String) -> String {
    let mut loud = text.to_uppercase();
    loud.push('!');
    loud
}

fn add_suffix(names: Vec<String>, suffix: &str) -> Vec<String> {
    let mut out = Vec::new();
    for name in names {
        let mut name = name;
        name.push_str(suffix);
        out.push(name);
    }
    out
}

unitTests:
test("report hands the vector back", || {
    let names = vec!["Ada".to_string(), "Grace".to_string(), "Linus".to_string()];
    let (text, names) = report(names);
    check_eq(text, "3 names: Ada, Grace, Linus");
    check_eq(names.len(), 3);
    let (text, _) = report(vec!["Ada".to_string()]);
    check_eq(text, "1 names: Ada");
    let (text, empty) = report(Vec::new());
    check_eq(text, "no names");
    check_eq(empty.len(), 0);
});

test("longest keeps the longer one", || {
    let a = String::from("tea");
    let b = String::from("coffee");
    check_eq(longest(a.clone(), b), "coffee");
    check_eq(longest(a.clone(), String::from("cup")), "tea");
    check_eq(longest(String::from("ab"), String::from("xyz")), "xyz");
    check_eq(a, "tea");
});

test("shout takes ownership", || {
    let s = String::from("hello");
    let loud = shout(s);
    check_eq(loud, "HELLO!");
    check_eq(shout(String::new()), "!");
});

test("add_suffix hands the vector back", || {
    let team = vec!["ada".to_string(), "bob".to_string()];
    let team = add_suffix(team, "@example.org");
    let team = add_suffix(team, "!");
    check_eq(team, vec!["ada@example.org!", "bob@example.org!"]);
    check_eq(add_suffix(Vec::new(), "x").len(), 0);
});

